use vstd::prelude::*;

verus! {
    fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> (replaced_list: Vec<i32>)
        requires
            first.len() > 0,
        ensures
            replaced_list.len() == first.len() - 1 + second.len(),
            forall |i: nat| (i < first.len() - 1) ==> (replaced_list[i] == first[i]),
            forall |j: nat| (j < second.len()) ==> (replaced_list[first.len() - 1 + j] == second[j]),
    {
        let mut replaced_list: Vec<i32> = Vec::new();
        
        // Append all elements of the first array except the last one
        let len_first = first.len() as nat;
        let len_second = second.len() as nat;

        // Invariant: replaced_list has the correct length and elements from first
        while replaced_list.len() < len_first - 1
            invariant
                replaced_list.len() <= len_first - 1,
                forall |i: nat| (i < replaced_list.len()) ==> (replaced_list[i] == first[i]),
            decreases len_first - 1 - replaced_list.len(),
        {
            replaced_list.push(first[replaced_list.len() as usize]);
        }

        // Append all elements of the second array
        let start_index = replaced_list.len();
        for j in 0..len_second
            invariant
                replaced_list.len() == start_index + j,
                replaced_list.len() <= len_first - 1 + len_second,
            decreases len_second - j,
        {
            replaced_list.push(second[j as usize]);
        }

        replaced_list
    }
}

